import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 16 .b8 sTile[];
.visible .entry conv2d_direct(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 total,
    .param .u32 batch,
    .param .u32 cin,
    .param .u32 hin,
    .param .u32 win,
    .param .u32 cout,
    .param .u32 kh,
    .param .u32 kw,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 hout,
    .param .u32 wout,
    .param .u32 has_bias
)
{
    .reg .pred p0, p1, p2, p3, p4, p5, p6, p7;
    .reg .u32 uTid, uNtid, uCta;
    .reg .u32 uTotal, uN, uCin, uH, uW, uCout, uKH, uKW;
    .reg .u32 uStrideH, uStrideW, uPadH, uPadW, uDilH, uDilW, uHout, uWout, uHasBias;
    .reg .u32 uTilesW, uTilesH, uSpatialTiles, uOcGroups, uSpatial, uTileW, uTileH, uOcGroup, uBatch;
    .reg .u32 uOcBase, uOcCount, uIcBase, uIcCount;
    .reg .u32 uShTile, uSwTile, uPlane, uStageCount, uStageIdx, uSBase, uSAddr;
    .reg .u32 uIcL, uGc, uRow, uCol, uIh, uIw;
    .reg .u32 uLocalW0, uLocalH0, uLocalW1, uLocalH1, uOh0, uOw0, uOh1, uOw1;
    .reg .u32 uSr0, uSc0, uSr1, uSc1, uIcPlane, uKh, uKw, uRowOff, uColOff, uR0, uR1, uC0, uC1;
    .reg .u32 uT0, uT1, uOc, uOff, uWBase, uOcStride, uOutPlane, uBatchOutBase, uOutBase;
    .reg .s32 sStrideH, sStrideW, sPadH, sPadW, sH, sW, sTileH0, sTileW0, sT0, sRow, sCol, sIh, sIw;
    .reg .u64 rdIn, rdW, rdB, rdOut, rdOff, rdAddr;
    .reg .f32 fX0, fX1, fWt, fBs;
    .reg .f32 fA0, fA1, fA2, fA3, fA4, fA5, fA6, fA7;
    .reg .f32 fA8, fA9, fA10, fA11, fA12, fA13, fA14, fA15;
    ld.param.u64 rdIn, [in_ptr];
    ld.param.u64 rdW, [w_ptr];
    ld.param.u64 rdB, [b_ptr];
    ld.param.u64 rdOut, [out_ptr];
    ld.param.u32 uTotal, [total];
    ld.param.u32 uN, [batch];
    ld.param.u32 uCin, [cin];
    ld.param.u32 uH, [hin];
    ld.param.u32 uW, [win];
    ld.param.u32 uCout, [cout];
    ld.param.u32 uKH, [kh];
    ld.param.u32 uKW, [kw];
    ld.param.u32 uStrideH, [stride_h];
    ld.param.u32 uStrideW, [stride_w];
    ld.param.u32 uPadH, [pad_h];
    ld.param.u32 uPadW, [pad_w];
    ld.param.u32 uDilH, [dil_h];
    ld.param.u32 uDilW, [dil_w];
    ld.param.u32 uHout, [hout];
    ld.param.u32 uWout, [wout];
    ld.param.u32 uHasBias, [has_bias];
    mov.u32 uTid, %tid.x;
    mov.u32 uNtid, %ntid.x;
    mov.u32 uCta, %ctaid.x;
    mov.u32 uSBase, sTile;
    add.u32 uTilesW, uWout, 31;
    div.u32 uTilesW, uTilesW, 32;
    add.u32 uTilesH, uHout, 15;
    div.u32 uTilesH, uTilesH, 16;
    mul.lo.u32 uSpatialTiles, uTilesW, uTilesH;
    add.u32 uOcGroups, uCout, 7;
    div.u32 uOcGroups, uOcGroups, 8;
    rem.u32 uSpatial, uCta, uSpatialTiles;
    div.u32 uT0, uCta, uSpatialTiles;
    rem.u32 uTileW, uSpatial, uTilesW;
    div.u32 uTileH, uSpatial, uTilesW;
    rem.u32 uOcGroup, uT0, uOcGroups;
    div.u32 uBatch, uT0, uOcGroups;
    shl.b32 uOcBase, uOcGroup, 3;
    sub.u32 uT0, uCout, uOcBase;
    setp.gt.u32 p0, uT0, 8;
    selp.u32 uOcCount, 8, uT0, p0;
    sub.u32 uT0, uKH, 1;
    mad.lo.u32 uShTile, uT0, uDilH, 1;
    mul.lo.u32 uT0, uStrideH, 15;
    add.u32 uShTile, uShTile, uT0;
    sub.u32 uT0, uKW, 1;
    mad.lo.u32 uSwTile, uT0, uDilW, 1;
    mul.lo.u32 uT0, uStrideW, 31;
    add.u32 uSwTile, uSwTile, uT0;
    mul.lo.u32 uPlane, uShTile, uSwTile;
    shl.b32 uStageCount, uPlane, 2;
    rem.u32 uLocalW0, uTid, 32;
    div.u32 uLocalH0, uTid, 32;
    add.u32 uT0, uTid, 256;
    rem.u32 uLocalW1, uT0, 32;
    div.u32 uLocalH1, uT0, 32;
    shl.b32 uT0, uTileH, 4;
    add.u32 uOh0, uT0, uLocalH0;
    add.u32 uOh1, uT0, uLocalH1;
    shl.b32 uT0, uTileW, 5;
    add.u32 uOw0, uT0, uLocalW0;
    add.u32 uOw1, uT0, uLocalW1;
    setp.lt.u32 p6, uOh0, uHout;
    setp.lt.u32 p0, uOw0, uWout;
    and.pred p6, p6, p0;
    setp.lt.u32 p7, uOh1, uHout;
    setp.lt.u32 p0, uOw1, uWout;
    and.pred p7, p7, p0;
    mul.lo.u32 uSr0, uLocalH0, uStrideH;
    mul.lo.u32 uSc0, uLocalW0, uStrideW;
    mul.lo.u32 uSr1, uLocalH1, uStrideH;
    mul.lo.u32 uSc1, uLocalW1, uStrideW;
    cvt.s32.u32 sStrideH, uStrideH;
    cvt.s32.u32 sStrideW, uStrideW;
    cvt.s32.u32 sPadH, uPadH;
    cvt.s32.u32 sPadW, uPadW;
    cvt.s32.u32 sH, uH;
    cvt.s32.u32 sW, uW;
    shl.b32 uT0, uTileH, 4;
    cvt.s32.u32 sT0, uT0;
    mul.lo.s32 sTileH0, sT0, sStrideH;
    sub.s32 sTileH0, sTileH0, sPadH;
    shl.b32 uT0, uTileW, 5;
    cvt.s32.u32 sT0, uT0;
    mul.lo.s32 sTileW0, sT0, sStrideW;
    sub.s32 sTileW0, sTileW0, sPadW;
    mul.lo.u32 uOcStride, uCin, uKH;
    mul.lo.u32 uOcStride, uOcStride, uKW;
    mul.lo.u32 uOutPlane, uHout, uWout;
    mul.lo.u32 uT0, uBatch, uCout;
    mul.lo.u32 uBatchOutBase, uT0, uOutPlane;
    mov.u32 uIcBase, 0;
    mov.f32 fA0, 0f00000000;
    mov.f32 fA1, 0f00000000;
    mov.f32 fA2, 0f00000000;
    mov.f32 fA3, 0f00000000;
    mov.f32 fA4, 0f00000000;
    mov.f32 fA5, 0f00000000;
    mov.f32 fA6, 0f00000000;
    mov.f32 fA7, 0f00000000;
    mov.f32 fA8, 0f00000000;
    mov.f32 fA9, 0f00000000;
    mov.f32 fA10, 0f00000000;
    mov.f32 fA11, 0f00000000;
    mov.f32 fA12, 0f00000000;
    mov.f32 fA13, 0f00000000;
    mov.f32 fA14, 0f00000000;
    mov.f32 fA15, 0f00000000;
L_CIN_TILE:
    setp.ge.u32 p0, uIcBase, uCin;
    @p0 bra L_ALL_DONE;
    sub.u32 uT0, uCin, uIcBase;
    setp.gt.u32 p0, uT0, 4;
    selp.u32 uIcCount, 4, uT0, p0;
    mov.u32 uStageIdx, uTid;
L_STAGE:
    setp.ge.u32 p0, uStageIdx, uStageCount;
    @p0 bra L_STAGE_DONE;
    div.u32 uIcL, uStageIdx, uPlane;
    rem.u32 uT0, uStageIdx, uPlane;
    rem.u32 uCol, uT0, uSwTile;
    div.u32 uRow, uT0, uSwTile;
    add.u32 uGc, uIcBase, uIcL;
    mov.f32 fX0, 0f00000000;
    setp.ge.u32 p0, uGc, uCin;
    @p0 bra L_STAGE_STORE;
    cvt.s32.u32 sRow, uRow;
    add.s32 sIh, sTileH0, sRow;
    setp.lt.s32 p0, sIh, 0;
    setp.ge.s32 p1, sIh, sH;
    or.pred p2, p0, p1;
    @p2 bra L_STAGE_STORE;
    cvt.s32.u32 sCol, uCol;
    add.s32 sIw, sTileW0, sCol;
    setp.lt.s32 p0, sIw, 0;
    setp.ge.s32 p1, sIw, sW;
    or.pred p2, p0, p1;
    @p2 bra L_STAGE_STORE;
    cvt.u32.s32 uIh, sIh;
    cvt.u32.s32 uIw, sIw;
    mad.lo.u32 uOff, uBatch, uCin, uGc;
    mad.lo.u32 uOff, uOff, uH, uIh;
    mad.lo.u32 uOff, uOff, uW, uIw;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdIn, rdOff;
    ld.global.nc.f32 fX0, [rdAddr];
L_STAGE_STORE:
    shl.b32 uT0, uStageIdx, 2;
    add.u32 uSAddr, uSBase, uT0;
    st.shared.f32 [uSAddr], fX0;
    add.u32 uStageIdx, uStageIdx, 256;
    bra L_STAGE;
L_STAGE_DONE:
    bar.sync 0;
    mov.u32 uIcL, 0;
L_COMP_IC:
    setp.ge.u32 p0, uIcL, uIcCount;
    @p0 bra L_COMP_IC_DONE;
    add.u32 uGc, uIcBase, uIcL;
    mul.lo.u32 uIcPlane, uIcL, uPlane;
    mov.u32 uKh, 0;
L_COMP_KH:
    setp.ge.u32 p0, uKh, uKH;
    @p0 bra L_COMP_KH_DONE;
    mul.lo.u32 uRowOff, uKh, uDilH;
    add.u32 uR0, uSr0, uRowOff;
    add.u32 uR1, uSr1, uRowOff;
    mov.u32 uKw, 0;
L_COMP_KW:
    setp.ge.u32 p0, uKw, uKW;
    @p0 bra L_COMP_KW_DONE;
    mul.lo.u32 uColOff, uKw, uDilW;
    add.u32 uC0, uSc0, uColOff;
    add.u32 uC1, uSc1, uColOff;
    mad.lo.u32 uOff, uR0, uSwTile, uC0;
    add.u32 uOff, uOff, uIcPlane;
    shl.b32 uOff, uOff, 2;
    add.u32 uSAddr, uSBase, uOff;
    ld.shared.f32 fX0, [uSAddr];
    mad.lo.u32 uOff, uR1, uSwTile, uC1;
    add.u32 uOff, uOff, uIcPlane;
    shl.b32 uOff, uOff, 2;
    add.u32 uSAddr, uSBase, uOff;
    ld.shared.f32 fX1, [uSAddr];
    mad.lo.u32 uWBase, uGc, uKH, uKh;
    mad.lo.u32 uWBase, uWBase, uKW, uKw;
    setp.ge.u32 p0, 0, uOcCount;
    @p0 bra L_W1;
    mov.u32 uOc, uOcBase;
    mad.lo.u32 uOff, uOc, uOcStride, uWBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdW, rdOff;
    ld.global.nc.f32 fWt, [rdAddr];
    fma.rn.f32 fA0, fX0, fWt, fA0;
    fma.rn.f32 fA8, fX1, fWt, fA8;
L_W1:
    setp.ge.u32 p0, 1, uOcCount;
    @p0 bra L_W2;
    add.u32 uOc, uOcBase, 1;
    mad.lo.u32 uOff, uOc, uOcStride, uWBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdW, rdOff;
    ld.global.nc.f32 fWt, [rdAddr];
    fma.rn.f32 fA1, fX0, fWt, fA1;
    fma.rn.f32 fA9, fX1, fWt, fA9;
L_W2:
    setp.ge.u32 p0, 2, uOcCount;
    @p0 bra L_W3;
    add.u32 uOc, uOcBase, 2;
    mad.lo.u32 uOff, uOc, uOcStride, uWBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdW, rdOff;
    ld.global.nc.f32 fWt, [rdAddr];
    fma.rn.f32 fA2, fX0, fWt, fA2;
    fma.rn.f32 fA10, fX1, fWt, fA10;
L_W3:
    setp.ge.u32 p0, 3, uOcCount;
    @p0 bra L_W4;
    add.u32 uOc, uOcBase, 3;
    mad.lo.u32 uOff, uOc, uOcStride, uWBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdW, rdOff;
    ld.global.nc.f32 fWt, [rdAddr];
    fma.rn.f32 fA3, fX0, fWt, fA3;
    fma.rn.f32 fA11, fX1, fWt, fA11;
L_W4:
    setp.ge.u32 p0, 4, uOcCount;
    @p0 bra L_W5;
    add.u32 uOc, uOcBase, 4;
    mad.lo.u32 uOff, uOc, uOcStride, uWBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdW, rdOff;
    ld.global.nc.f32 fWt, [rdAddr];
    fma.rn.f32 fA4, fX0, fWt, fA4;
    fma.rn.f32 fA12, fX1, fWt, fA12;
L_W5:
    setp.ge.u32 p0, 5, uOcCount;
    @p0 bra L_W6;
    add.u32 uOc, uOcBase, 5;
    mad.lo.u32 uOff, uOc, uOcStride, uWBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdW, rdOff;
    ld.global.nc.f32 fWt, [rdAddr];
    fma.rn.f32 fA5, fX0, fWt, fA5;
    fma.rn.f32 fA13, fX1, fWt, fA13;
L_W6:
    setp.ge.u32 p0, 6, uOcCount;
    @p0 bra L_W7;
    add.u32 uOc, uOcBase, 6;
    mad.lo.u32 uOff, uOc, uOcStride, uWBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdW, rdOff;
    ld.global.nc.f32 fWt, [rdAddr];
    fma.rn.f32 fA6, fX0, fWt, fA6;
    fma.rn.f32 fA14, fX1, fWt, fA14;
L_W7:
    setp.ge.u32 p0, 7, uOcCount;
    @p0 bra L_W_DONE;
    add.u32 uOc, uOcBase, 7;
    mad.lo.u32 uOff, uOc, uOcStride, uWBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdW, rdOff;
    ld.global.nc.f32 fWt, [rdAddr];
    fma.rn.f32 fA7, fX0, fWt, fA7;
    fma.rn.f32 fA15, fX1, fWt, fA15;
L_W_DONE:
    add.u32 uKw, uKw, 1;
    bra L_COMP_KW;
L_COMP_KW_DONE:
    add.u32 uKh, uKh, 1;
    bra L_COMP_KH;
L_COMP_KH_DONE:
    add.u32 uIcL, uIcL, 1;
    bra L_COMP_IC;
L_COMP_IC_DONE:
    add.u32 uT0, uIcBase, 4;
    setp.lt.u32 p0, uT0, uCin;
    @p0 bra L_LOOP_NEXT;
    setp.ge.u32 p0, 0, uOcCount;
    @p0 bra L_STORE_1;
    mov.u32 uOc, uOcBase;
    setp.eq.u32 p0, uHasBias, 0;
    @p0 bra L_BIAS_DONE_0;
    cvt.u64.u32 rdOff, uOc;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdB, rdOff;
    ld.global.nc.f32 fBs, [rdAddr];
    add.f32 fA0, fA0, fBs;
    add.f32 fA8, fA8, fBs;
L_BIAS_DONE_0:
    mad.lo.u32 uOutBase, uOc, uOutPlane, uBatchOutBase;
    mad.lo.u32 uOff, uOh0, uWout, uOw0;
    add.u32 uOff, uOff, uOutBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdOut, rdOff;
    @p6 st.global.f32 [rdAddr], fA0;
    mad.lo.u32 uOff, uOh1, uWout, uOw1;
    add.u32 uOff, uOff, uOutBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdOut, rdOff;
    @p7 st.global.f32 [rdAddr], fA8;
L_STORE_1:
    setp.ge.u32 p0, 1, uOcCount;
    @p0 bra L_STORE_2;
    add.u32 uOc, uOcBase, 1;
    setp.eq.u32 p0, uHasBias, 0;
    @p0 bra L_BIAS_DONE_1;
    cvt.u64.u32 rdOff, uOc;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdB, rdOff;
    ld.global.nc.f32 fBs, [rdAddr];
    add.f32 fA1, fA1, fBs;
    add.f32 fA9, fA9, fBs;
L_BIAS_DONE_1:
    mad.lo.u32 uOutBase, uOc, uOutPlane, uBatchOutBase;
    mad.lo.u32 uOff, uOh0, uWout, uOw0;
    add.u32 uOff, uOff, uOutBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdOut, rdOff;
    @p6 st.global.f32 [rdAddr], fA1;
    mad.lo.u32 uOff, uOh1, uWout, uOw1;
    add.u32 uOff, uOff, uOutBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdOut, rdOff;
    @p7 st.global.f32 [rdAddr], fA9;
L_STORE_2:
    setp.ge.u32 p0, 2, uOcCount;
    @p0 bra L_STORE_3;
    add.u32 uOc, uOcBase, 2;
    setp.eq.u32 p0, uHasBias, 0;
    @p0 bra L_BIAS_DONE_2;
    cvt.u64.u32 rdOff, uOc;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdB, rdOff;
    ld.global.nc.f32 fBs, [rdAddr];
    add.f32 fA2, fA2, fBs;
    add.f32 fA10, fA10, fBs;
L_BIAS_DONE_2:
    mad.lo.u32 uOutBase, uOc, uOutPlane, uBatchOutBase;
    mad.lo.u32 uOff, uOh0, uWout, uOw0;
    add.u32 uOff, uOff, uOutBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdOut, rdOff;
    @p6 st.global.f32 [rdAddr], fA2;
    mad.lo.u32 uOff, uOh1, uWout, uOw1;
    add.u32 uOff, uOff, uOutBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdOut, rdOff;
    @p7 st.global.f32 [rdAddr], fA10;
L_STORE_3:
    setp.ge.u32 p0, 3, uOcCount;
    @p0 bra L_STORE_4;
    add.u32 uOc, uOcBase, 3;
    setp.eq.u32 p0, uHasBias, 0;
    @p0 bra L_BIAS_DONE_3;
    cvt.u64.u32 rdOff, uOc;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdB, rdOff;
    ld.global.nc.f32 fBs, [rdAddr];
    add.f32 fA3, fA3, fBs;
    add.f32 fA11, fA11, fBs;
L_BIAS_DONE_3:
    mad.lo.u32 uOutBase, uOc, uOutPlane, uBatchOutBase;
    mad.lo.u32 uOff, uOh0, uWout, uOw0;
    add.u32 uOff, uOff, uOutBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdOut, rdOff;
    @p6 st.global.f32 [rdAddr], fA3;
    mad.lo.u32 uOff, uOh1, uWout, uOw1;
    add.u32 uOff, uOff, uOutBase;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdOut, rdOff;
    @p7 st.global.f32 [rdAddr], fA11;
L_STORE_4:
    setp.ge.u32 p0, 4, uOcCount;
    @p0 bra L_STORE_5;
    add.u32 uOc, uOcBase, 4;
    setp.eq.u32 p0, uHasBias, 0;
    @p0 bra L_BIAS_DONE_4;
    cvt.u64.u32 rdOff, uOc;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdB, rdOff;
